import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

/// Every sound the app can play. File: `assets/sounds/<name>.wav`
/// (generated by `tools/make_sounds.py`).
enum Sfx {
  tap('tap'),
  chip('chip'),
  error('error'),
  coin('coin'),
  spin('spin'),
  reelStop('reel_stop'),
  win('win'),
  bigWin('big_win'),
  lose('lose'),
  card('card'),
  cardFlip('card_flip'),
  blackjack('blackjack'),
  diceRoll('dice_roll'),
  rouletteSpin('roulette_spin'),
  ballDrop('ball_drop'),
  crashStart('crash_start'),
  crashTick('crash_tick'),
  cashOut('cash_out'),
  bust('bust');

  const Sfx(this.file);
  final String file;
}

/// Game sounds and the lobby music. Same idea as [AppHaptics]: a static switch
/// that the profile settings turn on and off, so a game just calls
/// `AppSound.play(Sfx.win)` and never checks a setting.
///
/// Sounds never throw. If audio is not available (a test, a simulator without
/// output) the call is silently ignored.
class AppSound {
  AppSound._();

  static bool enabled = true;
  static bool musicEnabled = true;

  static const int _voices = 6;
  static final List<AudioPlayer> _pool = [];
  static int _next = 0;
  static AudioPlayer? _music;
  static bool _musicWanted = false;
  static bool _ready = false;

  /// Sounds mixed in the game, quieter than a full-volume effect.
  static const double _sfxVolume = .9;
  static const double _musicVolume = .22;

  /// Call once at start-up. Lets the app's sounds mix with other apps' audio
  /// (a podcast keeps playing) instead of stopping them.
  static Future<void> init() async {
    if (_ready) return;
    _ready = true;
    try {
      await AudioPlayer.global.setAudioContext(AudioContextConfig(focus: AudioContextConfigFocus.mixWithOthers).build());
    } catch (e) {
      debugPrint('AppSound.init: $e');
    }
  }

  static void play(Sfx sfx, {double volume = 1}) {
    if (!enabled) return;
    unawaited(_play(sfx, volume));
  }

  static Future<void> _play(Sfx sfx, double volume) async {
    try {
      if (_pool.isEmpty) {
        for (var i = 0; i < _voices; i++) {
          final p = AudioPlayer();
          await p.setReleaseMode(ReleaseMode.stop);
          _pool.add(p);
        }
      }
      final p = _pool[_next];
      _next = (_next + 1) % _voices;
      await p.stop();
      await p.play(AssetSource('sounds/${sfx.file}.wav'), volume: (volume * _sfxVolume).clamp(0.0, 1.0));
    } catch (e) {
      debugPrint('AppSound.play(${sfx.file}): $e');
    }
  }

  /// Soft background loop. Safe to call again; it only starts once.
  static void startMusic() {
    _musicWanted = true;
    if (!musicEnabled) return;
    unawaited(_startMusic());
  }

  static Future<void> _startMusic() async {
    try {
      var m = _music;
      if (m == null) {
        m = AudioPlayer();
        await m.setReleaseMode(ReleaseMode.loop);
        _music = m;
      }
      if (m.state == PlayerState.playing) return;
      await m.play(AssetSource('sounds/music.wav'), volume: _musicVolume);
    } catch (e) {
      debugPrint('AppSound.music: $e');
    }
  }

  static void stopMusic() {
    _musicWanted = false;
    unawaited(_music?.pause().catchError((_) {}));
  }

  /// Apply the player's two switches. Starts or stops music to match.
  static void apply({required bool sound, required bool music}) {
    enabled = sound;
    musicEnabled = music;
    if (music && _musicWanted) {
      unawaited(_startMusic());
    } else if (!music) {
      unawaited(_music?.pause().catchError((_) {}));
    }
  }
}
